import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Three periods breathing in turn. It never speaks for itself: put the words
 * that say what's happening beside it ("Saving"), so it stays aria-hidden.
 */
function Spinner({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span data-slot="spinner" aria-hidden="true" className={cn("db-dots", className)} {...props}>
      <i />
      <i />
      <i />
    </span>
  )
}

export { Spinner }

@layer components {
  /* ── db-dots ── loading: three periods breathing in turn */
  .db-dots { display: inline-flex; align-items: center; gap: 0.3em; height: 1em; vertical-align: -0.1em; }
  .db-dots > i { width: 0.22em; height: 0.22em; border-radius: 50%; background: currentColor; animation: db-breathe 1280ms var(--db-breath) infinite; }
  .db-dots > i:nth-child(2) { animation-delay: 160ms; }
  .db-dots > i:nth-child(3) { animation-delay: 320ms; }
  @keyframes db-breathe { 0%, 100% { opacity: 0.18; translate: 0 0; } 40% { opacity: 1; translate: 0 -0.16em; } }
  @media (prefers-reduced-motion: reduce) { .db-dots > i { animation: none; opacity: 0.6; } }
}
